css:
/* Branch hours: a navy band over a road photograph with each department's hours under its icon, then a
   holiday note. Departments and hours come from Admin -> Locations -> Hours. */
[data-bz-section="branch-hours"] .bz-block { padding-block: 0; }
[data-bz-node^="hr-band"] { background: #003652 url("/contact/hero-road.jpg") center / cover; }
[data-bz-node^="hr-band"] > .bz-container { max-width: min(90vw, 1440px); padding: 0; }
[data-bz-node^="hr-row"] { display: flex; justify-content: center; padding: 62px 20px 52px; }
[data-bz-node^="hr-row"] > .bz-col { flex: 1 1 0; grid-column: auto; padding-inline: 10px; text-align: center; }
[data-bz-node^="hr-icon"] .bz-figure { margin: 0; display: flex; justify-content: center; }
[data-bz-node^="hr-icon"] img { width: 54px; height: 54px; border-radius: 0; }
[data-bz-node^="hr-row"] > .bz-col:nth-child(2) [data-bz-node^="hr-icon"] img { content: url("/location/dept-service.svg"); }
[data-bz-node^="hr-row"] > .bz-col:nth-child(3) [data-bz-node^="hr-icon"] img { content: url("/location/dept-parts.svg"); }
[data-bz-node^="hr-row"] > .bz-col:nth-child(4) [data-bz-node^="hr-icon"] img { content: url("/location/dept-inspections.svg"); }
[data-bz-section="branch-hours"] h3 { margin: 27px 0 0; text-align: center; font: 700 1.4rem / 1.2 var(--font-heading); color: #fff; letter-spacing: 0; }
[data-bz-node^="hr-sum"] .bz-text p { margin: 16px 0 0; text-align: center; white-space: pre-line; font: 600 0.95rem / 1.5 var(--font-body); color: #fff; max-width: none; }
[data-bz-node^="hr-note-band"] { background: #003652; padding: 28px 0 26px; }
[data-bz-node^="hr-note-band"] > .bz-container { max-width: min(90vw, 1440px); }
[data-bz-node^="hr-note"] .bz-text p { margin: 0; text-align: center; font: 400 1rem / 1.4 var(--font-body); color: #fff; max-width: none; }
[data-bz-node^="hr-note"] a { color: var(--accent); text-decoration: none; }
@media (max-width: 1100px) { [data-bz-node^="hr-row"] { flex-wrap: wrap; row-gap: 32px; } [data-bz-node^="hr-row"] > .bz-col { flex: 0 0 50%; } }
@media (max-width: 520px) { [data-bz-node^="hr-row"] > .bz-col { flex-basis: 100%; } }
